func missingMigrationVersions(ctx context.Context, provider *goose.Provider) ([]int64, error) {
	current, err := provider.GetDBVersion(ctx)
	if err != nil {
		return nil, err
	}
	statuses, err := provider.Status(ctx)
	if err != nil {
